import { createHmac } from "node:crypto";

const SEVEN_DAYS_S = 60 * 60 * 24 * 7;

export function signShareLink(invoiceId: string, now = Date.now()): string {
  const secret = process.env.SHARE_LINK_SECRET;
  if (!secret) throw new Error("SHARE_LINK_SECRET is not set");
  const expires = Math.floor(now / 1000) + SEVEN_DAYS_S;
  const sig = createHmac("sha256", secret).update(`${invoiceId}.${expires}`).digest("base64url");
  const base = process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";
  return `${base}/share/invoices/${invoiceId}?expires=${expires}&sig=${sig}`;
}

