import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";

const ROOTS = ["apps", "packages", "services"];
const SKIP = new Set(["node_modules", "dist", ".next", ".turbo", "coverage"]);
const PATTERN = /\b(TODO|FIXME)\b/g;

async function* walk(dir: string): AsyncGenerator<string> {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    if (SKIP.has(entry.name)) continue;
    const path = join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(path);
    else if (/\.(ts|tsx)$/.test(entry.name)) yield path;
  }
}

const counts: Record<string, { todo: number; fixme: number }> = {};
for (const root of ROOTS) {
  for (const pkg of await readdir(root)) {
    const tally = { todo: 0, fixme: 0 };
    for await (const file of walk(join(root, pkg))) {
      for (const match of (await readFile(file, "utf8")).matchAll(PATTERN)) {
        if (match[1] === "TODO") tally.todo++;
        else tally.fixme++;
      }
    }
    counts[`${root}/${pkg}`] = tally;
  }
}

const rows = Object.entries(counts).sort(([, a], [, b]) => b.todo + b.fixme - (a.todo + a.fixme));
process.stdout.write(rows.map(([name, c]) => `${name.padEnd(20)} TODO ${c.todo}  FIXME ${c.fixme}`).join("\n") + "\n");

